import{_ as s,h as a,o as i,aa as e}from"./chunks/framework.BsAE-16a.js";const u=JSON.parse('{"title":"一次“有控件无画面”的视频播放问题","description":"","frontmatter":{},"headers":[],"relativePath":"daily-notes/issue-30.md","filePath":"daily-notes/issue-30.md","lastUpdated":null}'),n={name:"daily-notes/issue-30.md"},l=e(`<h1 id="一次-有控件无画面-的视频播放问题" tabindex="-1">一次“有控件无画面”的视频播放问题 <a class="header-anchor" href="#一次-有控件无画面-的视频播放问题" aria-label="Permalink to &quot;一次“有控件无画面”的视频播放问题&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">原文地址</p><p><a href="https://github.com/wild2life/daily-notes/issues/30" target="_blank" rel="noreferrer">一次“有控件无画面”的视频播放问题 | GitHub</a></p></div><blockquote><p>最近在开发一个 Next.js 项目时，需要在页面中嵌入几个 MP4 视频，用的是标准的<code>&lt;video controls&gt;</code> 标签。 结果发现一个诡异的现象：三个视频使用了完全相同的 HTML 结构，其中两个可以正常显示画面，另一个却只出现了播放控件条，画面区域一片黑/白，时间轴可以拖动，但没有图像输出。 现象</p></blockquote><ul><li>页面代码完全一致，仅视频文件路径不同。 <ul><li>不正常的视频：VLN1.mp4</li><li>正常的视频：VLN2.mp4、VLA.mp4</li></ul></li><li>在本地文件夹中用系统播放器（如 VLC、Windows 媒体播放器）打开 VLN1.mp4 完全正常。</li><li>在浏览器（Chrome/Edge）以及 VSCode 的内置预览中均无法显示画面。</li></ul><h2 id="排查思路" tabindex="-1">排查思路 <a class="header-anchor" href="#排查思路" aria-label="Permalink to &quot;排查思路&quot;">​</a></h2><ol><li><p>排除前端代码问题 既然三个视频的 <code>&lt;video&gt;</code> 标签一模一样，且有两个能正常工作，说明不是代码逻辑、CSS 或 JavaScript 的问题。 也不是服务器 MIME 类型问题（因为同一个目录下的其他 MP4 能正常加载）。</p></li><li><p>怀疑视频编码格式不兼容 浏览器对视频编码的支持是有限制的。目前最广泛支持的是 H.264（AVC）视频 + AAC 音频 的组合。 很多现代浏览器不默认支持<code> H.265</code>（HEVC），因为专利授权复杂且硬件解码支持不统一。</p></li><li><p>使用 <code>ffprobe</code> 查看视频编码信息 安装 <code>ffmpeg</code> 后，可以用 <code>ffprobe </code>命令快速查看视频流的编码格式：</p></li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>ffprobe -v error -show_entries stream=codec_name,profile,level -of default=noprint_wrappers=1 VLN1.mp4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>输出结果：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>codec_name=hevc</span></span>
<span class="line"><span>profile=Main</span></span>
<span class="line"><span>level=120</span></span>
<span class="line"><span>codec_name=aac</span></span>
<span class="line"><span>profile=LC</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p>关键信息：codec_name=hevc —— 视频编码是<code> H.265</code>（HEVC），而音频是<code> AAC</code>（正常）。 再查看正常播放的 VLN2.mp4：</p></blockquote><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffprobe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> error</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -show_entries</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stream=codec_name,profile,level</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -of</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default=noprint_wrappers=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> VLN2.mp4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>输出：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>codec_name=aac</span></span>
<span class="line"><span>profile=LC</span></span>
<span class="line"><span>codec_name=h264</span></span>
<span class="line"><span>profile=High</span></span>
<span class="line"><span>level=40</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p>结论：正常视频是 <code>H.264</code> + <code>AAC</code>，问题视频是 <code>HEVC</code> + <code>AAC</code>。 浏览器不支持 <code>HEVC</code> 解码，所以只能解析出音频（如果有）和元数据（控件条能出现），但无法渲染视频帧。</p></blockquote><h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2><blockquote><p>将 VLN1.mp4 重新编码为<code> H.264</code> + <code>AAC</code>，并添加<code> faststart</code> 标志（将 moov 元数据移到文件头部，优化网页渐进式播放）。</p></blockquote><p>方法一：使用<code> ffmpeg</code> 命令行（推荐）</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffmpeg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> VLN1.mp4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -c:v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libx264</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -preset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> medium</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -crf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 23</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -c:a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aac</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -b:a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 128</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -movflags</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +faststart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  VLN1_fixed.mp4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="参数说明" tabindex="-1">参数说明： <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明：&quot;">​</a></h3><ul><li>c:v libx264：视频编码器改为 H.264</li><li>preset medium：编码速度与压缩率的平衡（可选：fast, medium, slow）</li><li>crf 23：恒定质量因子，18~28 之间，数值越小画质越好、体积越大；23 是默认值</li><li>c:a aac：音频编码为 AAC</li><li>b:a 128k：音频比特率 128kbps</li><li>movflags +faststart：将元数据移到文件开头，网页加载时无需下载完整文件即可开始播放</li></ul>`,20),p=[l];function t(r,c,d,o,h,k){return i(),a("div",null,p)}const m=s(n,[["render",t]]);export{u as __pageData,m as default};
